content.text:
{
  "name": "PWM转向舵机控制器",
  "name_en": "PWM Steering Servo Controller",
  "manufacturer": "",
  "description": "将输入的转向角映射为PWM脉冲并输出到转向执行机构的控制组件，通常用于RC小车或机器人小车的舵机转向控制。",
  "description_en": "A control component that maps requested steering angles to PWM pulses for a steering actuator, typically used to drive servo-based steering on RC cars or small robotic vehicles.",
  "actions": [
    {
      "action_name": "auto-update",
      "description": "更新PWM转向控制状态。",
      "description_en": "Update the PWM steering control state."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "根据输入转向角计算并输出对应的PWM转向脉冲（线程方式）。",
      "description_en": "Compute and output the corresponding PWM steering pulse from the requested steering angle in threaded mode."
    },
    {
      "action_name": "auto-run",
      "description": "根据输入转向角计算并输出对应的PWM转向脉冲。",
      "description_en": "Compute and output the corresponding PWM steering pulse from the requested steering angle."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭时将转向设置回直行位置。",
      "description_en": "Set the steering back to the straight-ahead position during shutdown."
    }
  ],
  "tag_hints": [
    "PWM steering",
    "servo control",
    "RC car steering",
    "steering actuator",
    "angle-to-pulse mapping",
    "robot vehicle control"
  ]
}

